import re

# r2 的正则掩码（已被 r3/r4/r5/r6 枚举掩码取代）：口令字符类排除 "/" 与空白，
# 且只掩第一个 "X:Y@" —— 口令含 "@"/空格/"/" 的形态照样原样落盘。
userinfo_re = re.compile(r"(?P<userinfo>[^/@\s:]*:[^/@\s]*)(?P<at>@)")

def _repl(match) -> str:
    userinfo = match.group("userinfo")
    if ":" not in userinfo:
        return match.group(0)
    return f"{userinfo.split(':', 1)[0]}:{_REDACTED}@"

return userinfo_re.sub(_repl, value, count=1)
